import ts from 'typescript';
const config=ts.readConfigFile('tsconfig.app.json',ts.sys.readFile);
if(config.error)throw Error(ts.flattenDiagnosticMessageText(config.error.messageText,'\n'));
const parsed=ts.parseJsonConfigFileContent(config.config,ts.sys,process.cwd());
const roots=['src/ui/scene-domain-results.ts','src/ui/scene-domain-results.test.ts'];
const program=ts.createProgram(roots,parsed.options);
const diagnostics=[...parsed.errors,...ts.getPreEmitDiagnostics(program)];
const host={getCanonicalFileName:p=>p,getCurrentDirectory:()=>process.cwd(),getNewLine:()=> '\n'};
if(diagnostics.length)process.stdout.write(ts.formatDiagnostics(diagnostics,host));
process.stdout.write(JSON.stringify({rootNames:roots,diagnostics:diagnostics.length,errors:diagnostics.filter(d=>d.category===ts.DiagnosticCategory.Error).length,optionsSource:'tsconfig.app.json unchanged'})+'\n');
process.exitCode=diagnostics.some(d=>d.category===ts.DiagnosticCategory.Error)?1:0;
